let _wordSet: Set<string> | null = null;
let _wordList: string[] | null = null;

export function getWordSet(): Set<string> {
  if (!_wordSet) {
    _wordList = RAW_WORDS.split(" ");
    _wordSet = new Set(_wordList);
  }
  return _wordSet;
}

export function getWordList(): string[] {
  if (!_wordList) {
    _wordList = RAW_WORDS.split(" ");
  }
  return _wordList;
}

export function isValidWord(word: string | null | undefined): boolean {
  if (!word || typeof word !== "string") return false;
  const clean = word.trim().toLowerCase();
  if (clean.length < 3 || clean.length > 8) return false;
  return getWordSet().has(clean);
}

export function calculateWordScore(word: string): WordScoreResult {
  const clean = (word || "").toUpperCase();
  let baseScore = 0;
  for (const char of clean) {
    for (const group in letterGroups) {
      if (group.includes(char)) {
        baseScore += letterGroups[group as LetterGroupKey];
        break;
      }
    }
  }

  // Length multiplier rewards longer words
  let multiplier = 1;
  if (clean.length === 4) multiplier = 1.5;
  else if (clean.length === 5) multiplier = 2.0;
  else if (clean.length === 6) multiplier = 2.5;
  else if (clean.length >= 7) multiplier = 3.0;

  const totalScore = Math.round(baseScore * multiplier);
  return { baseScore, multiplier, totalScore };
}

export function findPossibleWords(letters: string[]): string[] {
  if (!letters || !letters.length) return [];
  const counts: Record<string, number> = {};
  for (const l of letters) {
    const char = l.toLowerCase();
    counts[char] = (counts[char] || 0) + 1;
  }

  const list = getWordList();
  const maxLen = letters.length;
  const results: string[] = [];

  for (let i = 0; i < list.length; i++) {
    const word = list[i];
    if (word.length > maxLen) continue;

    const wCounts: Record<string, number> = {};
    let valid = true;
    for (let j = 0; j < word.length; j++) {
      const c = word[j];
      wCounts[c] = (wCounts[c] || 0) + 1;
      if (wCounts[c] > (counts[c] || 0)) {
        valid = false;
        break;
      }
    }

    if (valid) {
      results.push(word.toUpperCase());
    }
  }

  // Sort by length desc, then alphabetically
  return results.sort((a, b) => b.length - a.length || a.localeCompare(b));
}
